insert into public.deal (id, du_lieu, trang_thai, may_rui, da_dang_ky, hien_thi, bat_dau, ket_thuc) values ('BAC-HOA-DON', '{"bat_dau": "2026-11-14", "ket_thuc": "2026-11-29", "id": "BAC-HOA-DON", "ten": "Quà theo hóa đơn từ 800K", "ten_en": "Gift with purchase from 800K", "loai": "qua_theo_nguong_don", "nhom_qua": "hoa_don", "trang_thai": "DA_DUYET", "may_rui": false, "hien_thi": true, "dieu_kien": "Tính trên tổng hóa đơn sau giảm, mọi nhãn, gồm cả combo. Mỗi hóa đơn nhận quà của mốc cao nhất. Số lượng quà có hạn", "dieu_kien_en": "Based on the order total after discounts, all brands, combos included. Each order gets the gift of the highest tier reached. Limited quantity", "moc": [{"tu": 800000, "qua": "1 sữa rửa mặt LOPOE", "qua_en": "1 LOPOE cleansing foam", "gioi_han": 30}, {"tu": 1200000, "qua": "1 ampoule LOPOE", "qua_en": "1 LOPOE ampoule", "gioi_han": 15}], "hook": "Hóa đơn từ 800K tặng sữa rửa mặt LOPOE, từ 1,2 triệu tặng ampoule LOPOE", "hook_en": "Spend 800K for a free LOPOE cleanser, 1.2M for a free LOPOE ampoule"}'::jsonb, 'DA_DUYET', false, false, true, '2026-11-14', '2026-11-29') on conflict (id) do update set du_lieu = excluded.du_lieu, trang_thai = excluded.trang_thai, may_rui = excluded.may_rui, bat_dau = excluded.bat_dau, ket_thuc = excluded.ket_thuc;
insert into public.deal (id, du_lieu, trang_thai, may_rui, da_dang_ky, hien_thi, bat_dau, ket_thuc) values ('KM-09', '{"bat_dau": "2026-11-14", "ket_thuc": "2026-11-29", "id": "KM-09", "ten": "Voucher nhà hàng Union Square 15%", "ten_en": "15% Union Square restaurant voucher", "loai": "qua_theo_nguong_don", "nhom_qua": "cong_them", "trang_thai": "DA_DUYET", "may_rui": false, "hien_thi": true, "an_moc": true, "moc": [{"tu": 1000000, "qua": "1 voucher giảm 15% nhà hàng Union Square", "qua_en": "1 15% off Union Square restaurant voucher"}], "qua": "1 voucher giảm 15% nhà hàng Union Square", "qua_en": "1 15% off Union Square restaurant voucher", "dieu_kien": "Được tặng voucher nhà hàng Union Square 15%, cộng thêm với quà LOPOE. Nhân viên xác nhận tại quầy", "dieu_kien_en": "Get a 15% Union Square restaurant voucher, on top of the LOPOE gift. Staff confirm at the counter", "hook": "Được tặng voucher nhà hàng 15%", "hook_en": "Get a 15% restaurant voucher"}'::jsonb, 'DA_DUYET', false, false, true, '2026-11-14', '2026-11-29') on conflict (id) do update set du_lieu = excluded.du_lieu, trang_thai = excluded.trang_thai, may_rui = excluded.may_rui, bat_dau = excluded.bat_dau, ket_thuc = excluded.ket_thuc;
insert into public.deal (id, du_lieu, trang_thai, may_rui, da_dang_ky, hien_thi, bat_dau, ket_thuc) values ('DC-02', '{"bat_dau": "2026-11-14", "ket_thuc": "2026-11-29", "id": "DC-02", "ten": "Vòng quay may mắn", "ten_en": "Lucky wheel", "loai": "may_rui", "nhom_qua": "cong_them", "trang_thai": "DANG_CHAY", "may_rui": true, "da_dang_ky": true, "hien_thi": true, "an_moc": true, "moc": [{"tu": 1, "qua": "1 lượt quay vòng quay may mắn", "qua_en": "1 lucky-wheel spin"}], "qua": "1 lượt quay vòng quay may mắn", "qua_en": "1 lucky-wheel spin", "thuong_giu_hang": {"tu_ngay": "2026-11-27", "qua": "Thêm 1 lượt quay vòng quay may mắn", "qua_en": "1 extra lucky-wheel spin"}, "dieu_kien": "Mỗi hóa đơn tại VIVE được quay 1 lượt. Từ 27/11, giữ hàng trên web rồi nhận tại booth được thêm 1 lượt", "dieu_kien_en": "Every order at VIVE gets 1 spin. From 27/11, reserve on the web and pick up at the booth for 1 extra spin", "hook": "Mỗi hóa đơn tại VIVE được quay 1 lượt. Từ 27/11 giữ hàng trên web, thêm 1 lượt", "hook_en": "Every order at VIVE gets 1 spin. From 27/11, reserve on the web for an extra spin"}'::jsonb, 'DANG_CHAY', true, true, true, '2026-11-14', '2026-11-29') on conflict (id) do update set du_lieu = excluded.du_lieu, trang_thai = excluded.trang_thai, may_rui = excluded.may_rui, bat_dau = excluded.bat_dau, ket_thuc = excluded.ket_thuc;
